    const k = mode === 'cover' ? Math.max(viewW / worldW, viewH / worldH) : Math.min(viewW / worldW, viewH / worldH);
    return { k, tx: (viewW - worldW * k) / 2, ty: (viewH - worldH * k) / 2 };
